  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    # Build mappings
    node_by_id = {}
    children_by_parent = {}  # id -> list of child ids
    root_id = None
    for node in nodes:
        nid = node['id']
        node_by_id[nid] = node
        parent = node['parent']
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            children_by_parent.setdefault(parent, []).append(nid)
    if root_id is None:
        raise ValueError('No root found')
    # Check all parents exist
    for node in nodes:
        parent = node['parent']
        if parent is not None and parent not in node_by_id:
            raise ValueError('Parent not found: ' + parent)
    # Check required symbols exist
    all_symbols = {node['symbol'] for node in nodes}
    for req in required_symbols:
        if req not in all_symbols:
            raise ValueError('Required symbol missing: ' + req)
    # Precompute subtree node sets (original)
    def gather_descendants(nid):
        result = {nid}
        for child in children_by_parent.get(nid, []):
            result |= gather_descendants(child)
        return result
    subtree_nodes = {}
    for nid in node_by_id:
        subtree_nodes[nid] = gather_descendants(nid)
    # Sort nodes by depth descending, then id ascending
    sorted_ids = sorted(node_by_id.keys(), key=lambda nid: (-node_by_id[nid]['depth'], nid))
    retained = set(node_by_id.keys())
    removed_order = []
    # Helper to check if any descendant of nid is retained
    def has_descendant_retained(nid):
        for desc_id in subtree_nodes[nid]:
            if desc_id != nid and desc_id in retained:
                return True
        return False
    # Helper to get set of retained symbols outside a given node's subtree
    # but we only need to check required symbols
    for nid in sorted_ids:
        if nid not in retained:
            continue
        node = node_by_id[nid]
        if not node['removable']:
            continue
        if nid == root_id:
            continue
        # Check no descendant is retained (i.e., subtree empty of retained nodes except this node)
        if has_descendant_retained(nid):
            continue
        # Check that removing this node (and its empty subtree) does not lose any required symbol
        ok = True
        for req in required_symbols:
            # Look for any retained node with this symbol and not equal to nid
            found = False
            for other_id in retained:
                if other_id == nid:
                    continue
                if node_by_id[other_id]['symbol'] == req:
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok:
            retained.remove(nid)
            removed_order.append(nid)
    # Check that all required symbols are still present (should be true by construction)
    retained_symbols = {node_by_id[nid]['symbol'] for nid in retained}
    for req in required_symbols:
        if req not in retained_symbols:
            raise ValueError('Required symbol lost after reduction')
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }
